d3fendTechniques.ruleSnippet:
model host_process_tree {
  baseline: child_process_of('explorer.exe');
  flag_anomaly: true;
}

guardrail enforce_prompt_sanitization {
  block_patterns: ["ignore previous", "system:", "DAN mode"];
  isolate_context: true;
}

detect suspicious_ps {
  selection: Image|endswith: '\powershell.exe' AND CommandLine|contains: '-enc'
}

mqtt_acl on broker('192.168.10.1:8883') {
  allow publish to 'actuator/+/setpoint' only_from ['eng_workstation_cert'];
}
